BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ;
SELECT balance FROM accounts WHERE id = 1;
UPDATE accounts SET balance = balance - 100 WHERE id = 1;
COMMIT;

CREATE INDEX CONCURRENTLY idx_orders_cust_date ON orders (customer_id, created_at DESC);
CREATE INDEX idx_audit_meta ON audit_logs USING GIN (metadata);
CREATE INDEX idx_active_users ON users (email) WHERE deleted_at IS NULL;

SELECT relname, n_dead_tup, n_live_tup, last_autovacuum
FROM pg_stat_user_tables
ORDER BY n_dead_tup DESC LIMIT 10;

BEGIN;
SELECT id, payload FROM job_queue
WHERE status = 'pending'
ORDER BY created_at
FOR UPDATE SKIP LOCKED LIMIT 1;
-- process and mark done
COMMIT;

CREATE TABLE events (
    id BIGINT, created_at TIMESTAMPTZ NOT NULL, payload JSONB
) PARTITION BY RANGE (created_at);
CREATE TABLE events_2026_11 PARTITION OF events
FOR VALUES FROM ('2026-11-01') TO ('2026-12-01');

SELECT client_addr, state, sync_state,
       pg_wal_lsn_diff(pg_current_wal_lsn(), replay_lsn) AS lag_bytes
FROM pg_stat_replication;

ALTER TABLE invoices ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON invoices
USING (tenant_id = current_setting('app.current_tenant')::uuid);

SELECT id, metadata->>'plan' AS plan
FROM accounts
WHERE metadata @> '{"tier": "enterprise"}';

SET lock_timeout = '2s';
SET statement_timeout = '5s';
SELECT * FROM accounts WHERE id IN (10, 25) ORDER BY id ASC FOR UPDATE;

WITH recent_orders AS NOT MATERIALIZED (
  SELECT * FROM orders WHERE created_at >= NOW() - INTERVAL '7 days'
)
SELECT customer_id, COUNT(*) FROM recent_orders GROUP BY customer_id;
